/**
 * Writes app/theme.generated.css from theme.config.ts.
 * It runs before "npm run dev" and before "npm run build".
 *
 * The file has two parts:
 * 1. An "@theme" block that tells Tailwind CSS the colors this app added, so they are classes.
 * 2. One [data-theme] block for each theme, with the value of every level 2 token.
 */
import { writeFileSync } from "node:fs";
import { createTailwindTheme, createTheme } from "@toraline/tokens";
import { themeInputs } from "../theme.config.ts";

const header =
  "/* Written by scripts/write-theme-css.ts from theme.config.ts. Do not edit this file. */";
const css = [
  header,
  createTailwindTheme(themeInputs),
  ...themeInputs.map((themeInput) => createTheme(themeInput)),
].join("\n");
const outputPath = new URL("../app/theme.generated.css", import.meta.url);

writeFileSync(outputPath, css);
console.log(`Wrote app/theme.generated.css with ${themeInputs.length} themes.`);
